import Link from "next/link";
import { notFound } from "next/navigation";
import areas from "../../../../data/service-areas.json";
import RoavioLayout from "@/layout/RoavioLayout";

function findService(city, slug) {
  const area = areas.find((item) => item.city === city);

  const service = area?.services.find(
    (item) => item.slug === slug
  );

  return { area, service };
}

export async function generateMetadata({ params }) {
  const { city, slug } = await params;
  const { area, service } = findService(city, slug);

  if (!area || !service) {
    return { title: "Service Not Found" };
  }

  return {
    title: `${service.name} in ${area.name} | Heritage Tour Guide India`,
    description: service.summary,
  };
}

export default async function ServiceDetailPage({ params }) {
  const { city, slug } = await params;
  const { area, service } = findService(city, slug);

  if (!area || !service) {
    notFound();
  }

  return (
    <RoavioLayout>
    <main>
      <Link href={`/service-areas/${area.slug}`}>
        ← All Services in {area.name}
      </Link>

      <h1>
        {service.name} in {area.name}
      </h1>

      <p>{service.description}</p>

      <p>
        <strong>Duration:</strong> {service.duration}
      </p>

      <h2>Tour Highlights</h2>

      <ul>
        {service.highlights.map((highlight) => (
          <li key={highlight}>{highlight}</li>
        ))}
      </ul>

      <Link href="/contact">Enquire About This Tour</Link>
    </main>
    </RoavioLayout>
  );
}